insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-pile-mint-floor-98-2026-11-21','decision','The pile mint mints only where a route meets a 98% floor','S695 (SkyShearwater), 2026-11-21: the pile mint mints only where a route is right 98 times in 100 on held answers: the subject map on a code whose leave-one-out accuracy is 98% with 10 or more holders (4,772 of 4,863 on 21 codes), a shell kind the identity file homes, or a ruled kind. The 572-record S694 plan is not applied. His to revise. PR 3626.',array['commons','m-id','mint','pile','decide-and-record'],'proposed','PR 3626 (2db49276); kb/_pile_mint_dryrun.py',null,null,'SkyShearwater (S695)','2026-11-21'),
('d-tutoring-under-lskl-2026-11-21','decision','Bare Supervised Tutoring mints under LSKL','S695, 2026-11-21: bare Supervised Tutoring titles mint under LSKL, the Common SUBJ of Learning Assistance or Learning Skills (the MQ handbook names tutoring coordinators there; kb/discipline_canonical_subj4.json gives it LSKL, curator_override). Applied as LSKL M9004, 90 noncredit courses at 80 colleges. His to revise.',array['commons','m-id','mint','lskl','tutoring','decide-and-record'],'proposed','PR 3630; kb/pile_mint_out/2026-11-21_v3/apply_receipt.json',null,null,'SkyShearwater (S695)','2026-11-21'),
('d-pile-mint-source-value-2026-11-21','decision','Pile-minted records carry discipline_source pile_mint','S695, 2026-11-21: a pile-minted record carries discipline_source pile_mint with its route in pile_mint_route. kb/_infer_disciplines.py leaves it as written, _row_audit scores it session-mint (needs review), _ccr_confidence_score treats it as an anchor never trusted. His to revise. PR 3626.',array['commons','m-id','mint','discipline-source','decide-and-record'],'proposed','PR 3626 (2db49276)',null,null,'SkyShearwater (S695)','2026-11-21'),
('d-shell-kind-one-course-statewide-2026-11-21','decision','A generic kind mints as one common course per normalized title and band statewide','S695, 2026-11-21: a generic shell kind (tutoring, practicum, seminar) mints as one common course per normalized title and band statewide, never one per local subject; a numeral is a level and never folds. Grounds: the S694 plan split one course across SUBJ4s in 97 shell-title records (Supervised Tutoring across 9). His to revise.',array['commons','m-id','mint','shell-titles','decide-and-record'],'proposed','PR 3626; docs/commons_lessons.md S695',null,null,'SkyShearwater (S695)','2026-11-21'),
('d-held-codes-saved-in-subject-map-2026-11-21','decision','A person''s Common SUBJ for a local code is saved in the subject map by a committed PR','S695, 2026-11-21: a person''s Common SUBJ for a local subject code, chosen from #commons/subjects/held, is saved in kb/reference/subject_discipline_map.json by a committed PR. A college-keyed overlay would be a new write surface and goes through Governance and the privacy ADRs first (Rule 10 a3). His to revise.',array['commons','subjects','subject-map','governance','decide-and-record'],'proposed','docs/reference/lanes/commons.md; S695 session',null,null,'SkyShearwater (S695)','2026-11-21'),
('f-subject-map-route-recall-2026-11-21','fact','The subject map''s SUBJ4: 87.3% right on ordinary titles, 0 of 883 on generic shells','S695 second read, 2026-11-21: on identity-holding courses left out of their own vote, the subject map gives the right Common SUBJ for 45,079 of 51,624 (87.3%) and for 0 of 883 generic-shell titles (the identity file homes work experience, cooperative education and internship under WEXP). The S694 plan passed seven structural checks and failed this one.',array['commons','m-id','mint','subject-map','measured'],'proposed','PR 3626 second read; docs/commons_lessons.md S695',null,null,'SkyShearwater (S695)','2026-11-21'),
('f-pile-mint-v2-wave-2026-11-21','fact','Under the 98% floor the pile mint''s wave plans nothing on its own','S695, 2026-11-21: under the 98% floor the v2 plan plans 0 records of a wave of 1,599: 1,595 are shell titles with no convention (practicum 524, seminar 157, apprenticeship 149, supervised tutoring 146, tutoring 112). WEXP shell kinds measured 2,151 right, 0 wrong with each holder''s college left out. Only a ruled kind (tutoring under LSKL) minted.',array['commons','m-id','mint','pile','measured'],'proposed','kb/pile_mint_out/ (PR 3626)',null,null,'SkyShearwater (S695)','2026-11-21'),
('f-state-course-list-stale-2026-11-21','fact','The state course list is a May COCI export that no workflow rebuilds','S695, 2026-11-21: coci_lookup_data.js, the state course list, was built 2026-07-09 from a COCI export of 2026-05-21, and no workflow rebuilds it. Separately, 481 catalog rows'' committed cte differs from a fresh stamp (predates S695). Rebuilding from a current export is open work.',array['commons','coci','state-course-list','stale-data'],'proposed','S695 session; docs/commons_lessons.md S695',null,null,'SkyShearwater (S695)','2026-11-21'),
('f-held-codes-measured-2026-11-21','fact','Held subject codes after the v3 floor: 1,341 courses, 416 codes, 678 pairs','S695, 2026-11-21: #commons/subjects/held lists the local subject codes the pile mint holds on. At #3625''s merge: 943 courses, 341 codes, 474 college-and-code pairs. After #3626: 1,341 courses, 416 codes, 678 pairs (top OTA 27, CHIL 21, RT 21, KIN 20, CD 19). 168 other tutoring titles held: 76 name a subject, 70 prepare tutors, 22 other.',array['commons','subjects','held-codes','measured'],'proposed','kb/status/held_subject_codes.json; PRs 3625, 3626',null,null,'SkyShearwater (S695)','2026-11-21'),
('p-rollback-needs-file-formatting-2026-11-21','pitfall','A rollback that needs the file''s original formatting breaks once a build step rewrites it','S695, 2026-11-21: round one of #3626''s second read found the pile mint rollback failed once kb/_infer_disciplines.py rewrote kb/coci_minted_courses.json compact (BREAKS-THE-UNDO). A rollback must key on records, never on bytes or layout, and must read the live state, which this one did not.',array['mint','rollback','receipts','pitfall'],'proposed','PR 3626 review, round one',null,null,'SkyShearwater (S695)','2026-11-21'),
('p-watcher-output-wakes-no-one-2026-11-21','pitfall','A background watcher whose output wakes no one is not watching','S695, 2026-11-21: the COBIx watcher flagged #3358''s brief and issue #3628 at about 02:32Z; the conductor read them at 03:23Z, because a background command''s output does not wake the session, and the watcher then stopped at its two-hour limit. Read its output every few turns and restart it at the limit.',array['cobix','watcher','tooling','pitfall'],'proposed','S695 session transcript',null,null,'SkyShearwater (S695)','2026-11-21'),
('p-downstream-shrinks-on-upstream-change-2026-11-21','pitfall','A daily-build consumer can shrink silently when an upstream dry run changes what its lists mean','S695, 2026-11-21: when the pile mint dry run joined the daily build, the held-codes list fell from 943 courses to 3, because the dry run''s lists changed meaning; no step failed. After an upstream rule or output changes, read each downstream figure before merging.',array['daily-build','commons','subjects','pitfall'],'proposed','PR 3626 review',null,null,'SkyShearwater (S695)','2026-11-21'),
('p-copied-loader-misses-reservations-2026-11-21','pitfall','A copy of a shared loader misses a new reservation file','S695, 2026-11-21: round two of #3626''s review found the overmerge tool kept its own copy of the id-reservation loader, so it would not read kb/pile_mint_reserved.json and could re-mint a rolled-back id. 158 planned ids had already equaled ids in the staged, never-run kb/overmerge_out/2026-05-29/alias_map.json. Import a shared loader; never copy it.',array['m-id','mint','reservations','pitfall'],'proposed','PR 3626 review, round two',null,null,'SkyShearwater (S695)','2026-11-21'),
('m-first-pile-mint-record-2026-11-21','milestone','The first pile-minted record, and four PRs merged','S695, 2026-11-21: PRs 3624 (topics not applicable; pile 2,493 to 1,909), 3625 (#commons/subjects/held), 3627 (Subjects builders in the daily build) and 3626 (pile mint v3: the floor and the apply) merged. PR 3630 minted LSKL M9004 Supervised Tutoring, 90 noncredit courses at 80 colleges, the first pile-mint record; open at this writing.',array['commons','m-id','mint','milestone'],'proposed','PRs 3624, 3625, 3626, 3627, 3630',null,null,'SkyShearwater (S695)','2026-11-21')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
